import json

from .content import quality
from .db import now, uid


def seed_demo(db):
    existing = db.one("SELECT id FROM sites WHERE demo=1")
    if existing:
        return existing["id"]
    site_id = uid()
    profile = {"business": "فروشگاه نمونه قهوه و تجهیزات دم‌آوری", "audience": "علاقه‌مندان به قهوه خانگی",
               "language": "فارسی", "tone": "صمیمی و دقیق", "market": "ایران", "forbidden": "ادعاهای درمانی و قیمت تأییدنشده"}
    analysis = {"summary": "یک فروشگاه نمونه برای آشنایی با جریان کار. همه داده‌های این پروژه نمایشی‌اند.",
                "audience": "علاقه‌مندان به دم‌آوری قهوه در خانه", "cms": "WordPress", "sitemap_found": True,
                "analyzed_at": now(), "warnings": ["داده‌های نمونه؛ هیچ سایت واقعی خوانده نشده است."],
                "pages": [{"url": "https://example.com/coffee", "title": "انتخاب قهوه برای خانه", "text": "داده نمایشی"},
                          {"url": "https://example.com/brewing", "title": "وسایل دم‌آوری", "text": "داده نمایشی"}]}
    db.execute("INSERT INTO sites(id,name,url,profile,analysis,demo,created_at) VALUES(?,?,?,?,?,1,?)",
               (site_id, "قهوه‌خانه · پروژه نمونه", "https://example.com", json.dumps(profile, ensure_ascii=False),
                json.dumps(analysis, ensure_ascii=False), now()))
    proposals = [("راهنمای انتخاب آسیاب قهوه برای خانه", "آسیاب قهوه", "commercial"),
                 ("چرا قهوه خانگی تلخ می‌شود؟", "تلخی قهوه", "informational"),
                 ("فرنچ پرس یا موکاپات؛ کدام برای شما مناسب‌تر است؟", "فرنچ پرس یا موکاپات", "commercial"),
                 ("نگهداری قهوه در خانه؛ اشتباهات رایج", "نگهداری قهوه", "informational")]
    for title, keyword, intent in proposals:
        db.execute("INSERT INTO topics(id,site_id,title,keyword,intent,rationale,outline) VALUES(?,?,?,?,?,?,?)",
                   (uid(), site_id, title, keyword, intent, "پیشنهاد نمایشی برای پوشش پرسش مخاطب و ارتباط با محصولات فروشگاه.",
                    json.dumps(["پاسخ کوتاه", "راهنمای انتخاب", "اشتباهات متداول", "پرسش‌های رایج"], ensure_ascii=False)))
    topic = db.one("SELECT * FROM topics WHERE site_id=? LIMIT 1", (site_id,))
    content = """<p>انتخاب آسیاب قهوه برای خانه از شناخت روش دم‌آوری شروع می‌شود. اندازه ذرات قهوه روی سرعت عبور آب و طعم نوشیدنی اثر می‌گذارد؛ بنابراین پیش از مقایسه مدل‌ها، مشخص کنید بیشتر از چه وسیله‌ای استفاده می‌کنید.</p>
<h2>ابتدا روش دم‌آوری خود را مشخص کنید</h2><p>اگر معمولاً با فرنچ پرس قهوه آماده می‌کنید، به تنظیمی متفاوت از اسپرسو نیاز دارید. دستگاهی را انتخاب کنید که تنظیمات آن با وسیله شما سازگار باشد. داشتن تعداد زیادی درجه تنظیم به‌تنهایی نشان نمی‌دهد که یک آسیاب برای همه روش‌ها مناسب است. توضیحات سازنده و تجربه عملی کاربران را کنار هم بررسی کنید.</p>
<h2>آسیاب دستی یا برقی؟</h2><p>آسیاب دستی برای کسی که هر بار مقدار کمی قهوه آماده می‌کند می‌تواند انتخاب قابل بررسی باشد. این ابزار معمولاً فضای کمی می‌گیرد، اما چرخاندن دسته به زمان و انرژی نیاز دارد. اگر هر روز برای چند نفر قهوه آماده می‌کنید، راحتی استفاده از مدل برقی اهمیت بیشتری پیدا می‌کند. پیش از خرید به محل قرارگیری دستگاه و دسترسی به برق هم فکر کنید.</p>
<h2>تنظیم و تمیزکردن چقدر ساده است؟</h2><p>ابزاری که استفاده روزانه از آن دشوار باشد ممکن است به‌مرور کنار گذاشته شود. بررسی کنید تنظیم آسیاب واضح و قابل تکرار باشد و بتوانید قطعات لازم را طبق راهنمای سازنده تمیز کنید. همه قطعات برای شست‌وشو با آب مناسب نیستند؛ دستور نگهداری همان محصول را بخوانید.</p>
<h2>پیش از خرید این موارد را مقایسه کنید</h2><ul><li>سازگاری با روش دم‌آوری اصلی شما</li><li>سهولت تنظیم و تکرار درجه آسیاب</li><li>ظرفیت مورد نیاز و زمان آماده‌سازی</li><li>دسترسی به راهنمای نگهداری و خدمات</li></ul><p>بودجه را با تعداد دفعات استفاده و نیاز واقعی خود هماهنگ کنید. اگر امکان آزمایش وجود دارد، با قهوه و وسیله‌ای مشابه مصرف روزانه خود دستگاه را امتحان کنید. برای اطلاعات بیشتر درباره ابزارها می‌توانید <a href="https://example.com/brewing">راهنمای تجهیزات دم‌آوری</a> را ببینید.</p>
<h2>آیا یک تنظیم ثابت همیشه نتیجه یکسان می‌دهد؟</h2><p>نوع دانه، میزان برشته‌کاری و روش دم‌آوری می‌توانند نیاز به تنظیم را تغییر دهند. یک نقطه شروع انتخاب کنید و هر بار تنها یک متغیر را تغییر دهید. ثبت مقدار قهوه، آب و درجه آسیاب کمک می‌کند تغییر طعم را بهتر بفهمید و نتیجه دلخواه را تکرار کنید.</p><p>این مقاله بخشی از پروژه نمایشی است. پیش از استفاده تجاری، مشخصات محصولات و توصیه‌های فنی باید با منابع معتبر بررسی شوند.</p>"""
    draft = {"title": topic["title"], "keyword": topic["keyword"], "content_html": content,
             "meta_description": "برای انتخاب آسیاب قهوه خانگی، روش دم‌آوری، راحتی تنظیم، نگهداری و میزان استفاده روزانه خود را بررسی کنید و انتخاب آگاهانه‌تری داشته باشید.",
             "sources": [{"title": "راهنمای تجهیزات · منبع نمایشی", "url": "https://example.com/brewing"}]}
    db.execute("""INSERT INTO articles(id,site_id,topic_id,title,keyword,slug,meta_description,content_html,excerpt,
               brief,sources,quality,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
               (uid(), site_id, topic["id"], draft["title"], draft["keyword"], "home-coffee-grinder", draft["meta_description"],
                content, "انتخاب آسیاب متناسب با روش دم‌آوری و مصرف روزانه.", "هدف: کمک به انتخاب ابزار خانگی. این محتوا نمونه است.",
                json.dumps(draft["sources"], ensure_ascii=False), json.dumps(quality(draft), ensure_ascii=False), now(), now()))
    db.execute("UPDATE topics SET status='drafted' WHERE id=?", (topic["id"],))
    db.event(site_id, "پروژه نمونه ساخته شد؛ بدون تماس با سایت یا سرویس خارجی")
    return site_id
